const removeDuplicates = (arr) => {
  const seen = new Set();
  const result = [];

  arr.forEach((element) => {
    const hasSeen = seen.has(element);
    if (!hasSeen) {
      seen.add(element);
      result.push(element);
    }
  });

  return result;
};

