  const uniqueElements = new Set();
  const processed = arr.filter((item) => {
    const isNew = !uniqueElements.has(item);
    if (isNew) {
      uniqueElements.add(item);
    }
    return isNew;
  });
  return processed;
};

const compose = (f, g) => (x) => f(g(x));

const removeDuplicatesComposed = compose(convertToArray, mapToSet);

