const splitIntoWords = str => str.split(' ');

const removePunctuation = word => word.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, '');

const sanitizeWord = word => removePunctuation(word).toLowerCase();

const getLength = word => word.length;

const findLongestWord = str => {
  const words = splitIntoWords(str);

  let longestWord = '';
  let maxLength = 0;

  words.forEach(word => {
    const cleanWord = sanitizeWord(word);
    const currentLength = getLength(cleanWord);

    if (currentLength > maxLength) {
      maxLength = currentLength;
      longestWord = cleanWord;
    }
  });

  return longestWord;
};

