const multiply = (a, b) => a * b;

const square = n => multiply(n, n);

const calculateCircleArea = radius => {
  const pi = Math.PI;
  const radiusSquared = square(radius);
  const area = multiply(pi, radiusSquared);
  return area;
};

const formatOutput = (area, precision = 2) => area.toFixed(precision);

const logResult = (radius, areaFormatter = formatOutput) => {
  const area = calculateCircleArea(radius);
  console.log(`Area of circle with radius ${radius}: ${areaFormatter(area)}`);
};

// Example usage:
logResult(1, a => `Exact: ${a}`);
logResult(2);
logResult(3.5, a => a.toExponential(3));

