const validateSides = (sides) => {
  if (!Number.isInteger(sides)) {
    throw new TypeError(`sides must be an integer, got ${typeof sides}: ${sides}`);
  }
  if (sides < 2) {
    throw new RangeError(`a dice needs at least 2 sides, got ${sides}`);
  }
  return sides;
};

const rollDice = (sides) => {
  validateSides(sides);
  return Math.floor(Math.random() * sides) + 1;
};

const rollMany = (sides, times) => {
  validateSides(sides);
  if (!Number.isInteger(times) || times < 1) {
    throw new RangeError(`times must be a positive integer, got ${times}`);
  }
  return Array.from({ length: times }, () => rollDice(sides));
};

const tally = (rolls) => {
  const counts = new Map();
  rolls.forEach((face) => counts.set(face, (counts.get(face) || 0) + 1));
  return counts;
};

const sum = (rolls) => rolls.reduce(
  (total, face) => total + face,
  0,
);

const mean = (rolls) => sum(rolls) / rolls.length;

const rollAndSum = (sides, dice) => sum(rollMany(sides, dice));

const formatHistogram = (sides, rolls) => {
  const counts = tally(rolls);
  const faces = Array.from({ length: sides }, (_, i) => i + 1);
  const widest = Math.max(...faces.map((face) => String(face).length));
  const scale = (count) => Math.round((count / rolls.length) * 50);
  const lines = faces.map((face) => {
    const count = counts.get(face) || 0;
    const label = String(face).padStart(widest, ' ');
    const bar = '#'.repeat(scale(count));
    return `${label} | ${bar} ${count}`;
  });
  return lines.join('\n');
};

const describe = (sides, times) => {
  const rolls = rollMany(sides, times);
  const expected = (sides + 1) / 2;
  return [
    `d${sides} rolled ${times} times`,
    formatHistogram(sides, rolls),
    `observed mean ${mean(rolls).toFixed(3)} (expected ${expected.toFixed(3)})`,
  ].join('\n');
};

const main = () => {
  console.log(`single d6: ${rollDice(6)}`);
  console.log(`single d20: ${rollDice(20)}`);
  console.log(`3d6 total: ${rollAndSum(6, 3)}`);
  console.log(describe(6, 600));
  console.log(describe(20, 2000));
  try {
    rollDice(1.5);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
};

main();

module.exports = { rollDice, rollMany, rollAndSum, tally, sum, mean, formatHistogram, describe };

