const getFileExtension = filename => {
  const parts = filename.split('.');

  const getLastTwoParts = arr => arr.slice(-2);

  const getFirstPartLength = arr => arr[0].length;

  const isMultiPartExtension = arr =>
    arr.length > 2 && getFirstPartLength(getLastTwoParts(arr)) <= 3;

  const getExtension = arr => {
    if (arr.length === 1) return '';
    return isMultiPartExtension(arr)
      ? arr.slice(-2).join('.')
      : arr.pop();
  };

  const finalExtension = getExtension(parts);

  const toLowerCase = str => str.toLowerCase();

  return toLowerCase(finalExtension);
};

