const parseCsvLine = (line) => {
  const trimSpace = (str) => str.trim();

  const splitByComma = (str) => str.split(',');

  const processValues = (values) => values.map(trimSpace);

  const filterEmpty = (values) => values.filter(val => val !== '');

  const pipe = (...fns) => (x) => fns.reduce((v, f) => f(v), x);

  const cleanAndSplit = pipe(
    splitByComma,
    processValues,
    filterEmpty
  );

  return cleanAndSplit(line);
};

