const calculateMode = numbers => {
  if (numbers.length === 0) return [];

  const counts = {};
  numbers.forEach(num => counts[num] = (counts[num] || 0) + 1);

  const getValues = obj => Object.values(obj);
  const maxCount = Math.max(...getValues(counts));

  const isMode = count => count === maxCount;
  const filterModes = ([num, count]) => isMode(count);

  const getNumber = ([num, count]) => Number(num);

  return Object.entries(counts)
    .filter(filterModes)
    .map(getNumber);
};

