const isString = value => typeof value === 'string';

const validateInput = strs => {
  if (!Array.isArray(strs)) {
    throw new TypeError('longestCommonPrefix expects an array of strings');
  }
  const bad = strs.findIndex(item => !isString(item));
  if (bad !== -1) {
    throw new TypeError(`element at index ${bad} is not a string`);
  }
  return strs;
};

const commonPrefixOfPair = (a, b) => {
  const limit = Math.min(a.length, b.length);
  let i = 0;
  while (i < limit && a[i] === b[i]) {
    i += 1;
  }
  return a.slice(0, i);
};

const longestCommonPrefix = strs => {
  validateInput(strs);
  if (strs.length === 0) {
    return '';
  }
  return strs.reduce((prefix, word) => {
    if (prefix === '') {
      return '';
    }
    return commonPrefixOfPair(prefix, word);
  });
};

const groupByPrefix = words => {
  const buckets = new Map();
  words.forEach(word => {
    const key = word.charAt(0);
    const bucket = buckets.get(key);
    if (bucket) {
      bucket.push(word);
    } else {
      buckets.set(key, [word]);
    }
  });
  return buckets;
};

const describe = words => {
  const prefix = longestCommonPrefix(words);
  const shown = words.map(word => `"${word}"`).join(', ');
  const label = prefix === '' ? 'no common prefix' : `prefix "${prefix}"`;
  return `[${shown}] -> ${label}`;
};

const report = groups => {
  const lines = [];
  groups.forEach((words, key) => {
    lines.push(`group '${key}': ${describe(words)}`);
  });
  return lines.join('\n');
};

