const sumDigits = n => n.toString().split('').reduce((acc, digit) => acc + parseInt(digit), 0);

const doubleAndSum = n => {
  const doubled = n * 2;
  return doubled > 9 ? sumDigits(doubled) : doubled;
};

const processDigit = (digit, index, length) => {
  const parsedDigit = parseInt(digit, 10);
  return (length - 1 - index) % 2 === 1
    ? doubleAndSum(parsedDigit)
    : parsedDigit;
};

const calculateLuhnSum = cardNumber => {
  const cardLength = cardNumber.length;
  return cardNumber
    .split('')
    .reduce((total, digit, index) => total + processDigit(digit, index, cardLength), 0);
};

const isValidCreditCard = cardNumber => {
  const totalSum = calculateLuhnSum(cardNumber);
  return totalSum % 10 === 0;
};

