const multiplyStrings = (num1, num2) => {
  if (num1 === '0' || num2 === '0') return '0';
  const n1 = num1.split('').reverse().map(Number);
  const n2 = num2.split('').reverse().map(Number);

  const product = Array(n1.length + n2.length).fill(0);

  n1.forEach((digit1, i) => {
    n2.forEach((digit2, j) => {
      product[i + j] += digit1 * digit2;
    });
  });

  let carry = 0;
  const resultDigits = product.map((val, k) => {
    const sum = val + carry;
    carry = Math.floor(sum / 10);
    return sum % 10;
  });

  while (carry > 0) {
    resultDigits.push(carry % 10);
    carry = Math.floor(carry / 10);
  }

  return resultDigits.reverse().join('').replace(/^0+/, '') || '0';
};

const largeFactorial = (n) => {
  if (n < 0) return '0';
  if (n === 0 || n === 1) return '1';

  let res = '1';
  const range = Array.from({
    length: n - 1
  }, (_, i) => i + 2);

  range.forEach(num => {
    res = multiplyStrings(res, String(num));
  });

  return res;
};

