const firstUniqChar = s => {
  const charCounts = {};

  s.split('').forEach(char => {
    charCounts[char] = (charCounts[char] || 0) + 1;
  });

  const findIndex = (char, index) => charCounts[char] === 1 ? index : -1;

  for (let i = 0; i < s.length; i++) {
    const char = s[i];
    const result = findIndex(char, i);
    if (result !== -1) return result;
  }

  const noUniques = () => -1;
  return noUniques();
};

