class Queue {
  #items = [];
  #head = 0;

  enqueue(value) {
    this.#items.push(value);
    return this;
  }

  dequeue() {
    if (this.#head >= this.#items.length) return null;
    const value = this.#items[this.#head];
    this.#items[this.#head] = undefined;
    this.#head += 1;
    if (this.#head > 32 && this.#head * 2 >= this.#items.length) {
      this.#items = this.#items.slice(this.#head);
      this.#head = 0;
    }
    return value;
  }

  peek() {
    return this.#head < this.#items.length ? this.#items[this.#head] : null;
  }

  get size() {
    return this.#items.length - this.#head;
  }

  toArray() {
    return this.#items.slice(this.#head);
  }
}

const parseCommand = line => {
  const text = line.trim();
  if (text === '') return null;
  const [name, rawArg] = text.split(/\s+/);
  const numeric = Number(rawArg);
  const arg = rawArg === undefined || Number.isNaN(numeric) ? rawArg : numeric;
  return { name: name.toLowerCase(), arg };
};

const applyCommand = (queue, { name, arg }) => {
  if (name === 'enqueue') {
    queue.enqueue(arg);
    return `enqueue ${arg} -> size ${queue.size}`;
  }
  if (name === 'dequeue') return `dequeue -> ${queue.dequeue()}`;
  if (name === 'peek') return `peek -> ${queue.peek()}`;
  throw new Error(`unknown command: ${name}`);
};

const runScript = (queue, lines) =>
  lines
    .map(parseCommand)
    .filter(command => command !== null)
    .map(command => applyCommand(queue, command));

const formatSnapshot = queue => `front -> [${queue.toArray().join(', ')}] <- back`;

const countDequeues = log =>
  log.filter(entry => entry.startsWith('dequeue')).length;

const script = [
  'enqueue 1',
  'enqueue 2',
  'peek',
  'dequeue',
  'enqueue ticket-42',
  'dequeue',
  'dequeue',
  '',
  'dequeue'
];

const queue = new Queue();
const log = runScript(queue, script);
log.forEach(entry => console.log(entry));
console.log(formatSnapshot(queue));
console.log(`removed ${countDequeues(log)} items, ${queue.size} remaining`);

