const sumArray = arr => arr.reduce((acc, val) => acc + val, 0);

const calculateAverage = arr => sumArray(arr) / arr.length;

const getWindow = (data, index, windowSize) => data.slice(index, index + windowSize);

const simpleMovingAverage = (data, windowSize) => {
  const numWindows = data.length - windowSize + 1;
  const generateWindowAverages = (acc, _, i) => {
    const currentWindow = getWindow(data, i, windowSize);
    return [...acc, calculateAverage(currentWindow)];
  };

  return Array.from({
    length: numWindows
  }).reduce(generateWindowAverages, []);
};

const mapToAverage = windowData => calculateAverage(windowData);

const calculateMovingAverage = (data, windowSize) => {
  if (windowSize <= 0 || windowSize > data.length) return [];

  const createWindows = (_, i) => data.slice(i, i + windowSize);

  return Array.from({
    length: data.length - windowSize + 1
  }, createWindows)
    .map(mapToAverage);
};

const simpleMovingAverageFinal = (data, windowSize) => {
  if (windowSize <= 0 || windowSize > data.length) return [];

  const results = [];
  for (let i = 0; i <= data.length - windowSize; i++) {
    const currentWindow = data.slice(i, i + windowSize);
    results.push(calculateAverage(currentWindow));
  }
  return results;
};

