const stringPermutations = (str) => {
  if (str.length === 0) return [''];

  const permutations = new Set();

  const generatePermutations = (currentPerm, remainingChars) => {
    if (remainingChars.length === 0) {
      permutations.add(currentPerm);
      return;
    }

    remainingChars.split('').forEach((char, index) => {
      const newRemaining = remainingChars.slice(0, index) + remainingChars.slice(index + 1);
      generatePermutations(currentPerm + char, newRemaining);
    });
  };

  generatePermutations('', str);

  const result = Array.from(permutations);
  return result;
};

