const stringPermutations = function(str) {
  if (str.length === 0) return [''];

  const permutations = new Set();

  const generatePermutations = function(currentPerm, remainingChars) {
    if (remainingChars.length === 0) {
      permutations.add(currentPerm);
      return;
    }

    remainingChars.split('').forEach(function(char, index) {
      const newRemaining = remainingChars.slice(0, index) + remainingChars.slice(index + 1);
      generatePermutations(currentPerm + char, newRemaining);
    });
  };

  generatePermutations('', str);

  const result = Array.from(permutations);
  return result;
};

const uniquePermutations = function(str) {
  const result = stringPermutations(str);
  return result;
};

const getFirstChar = function(s) { return s[0]; };
const getRemaining = function(s) { return s.substring(1); };

