  if (n <= 0) return false;
  const isEven = num => num % 2 === 0;
  const divideByTwo = num => num / 2;

  let current = n;
  while (current > 1) {
    if (!isEven(current)) return false;
    current = divideByTwo(current);
  }
  return true;
};

