  const sortedEvents = [...events].sort((a, b) => a.start - b.start);

  const isOverlapping = (event1, event2) => event1.end > event2.start && event2.end > event1.start;

  const checkAdjacent = (current, next) => isOverlapping(current, next);

  for (let i = 0; i < sortedEvents.length - 1; i++) {
    if (checkAdjacent(sortedEvents[i], sortedEvents[i + 1])) {
      return true;
    }
  }
  return false;
};

