const reverseStr = str => str.split('').reverse().join('');

const charToNum = char => parseInt(char, 10);

const calculatePower = (base, exponent) => Math.pow(base, exponent);

const multiplyAndSum = (acc, digit, index) => acc + digit * calculatePower(2, index);

const binaryToDecimal = binaryStr => {
  const reversedBinary = reverseStr(binaryStr);
  const digits = reversedBinary.split('').map(charToNum);
  const decimal = digits.reduce((acc, digit, index) => multiplyAndSum(acc, digit, index), 0);
  return decimal;
};

