const findFirstDuplicate = (nums) => {
  const seen = new Set();
  const checkAndAdd = (num) => {
    if (seen.has(num)) {
      return true;
    }
    seen.add(num);
    return false;
  };
  const findDuplicate = (arr) => {
    for (let i = 0; i < arr.length; i++) {
      const currentNum = arr[i];
      if (checkAndAdd(currentNum)) {
        return currentNum;
      }
    }
    return -1;
  };
  const result = findDuplicate(nums);
  const negateIfNegative = (val) => val < 0 ? -1 : val;
  return negateIfNegative(result);
};

