const getNestedProperty = (obj, path) => {
  const reducePath = (accumulator, currentKey) => {
    if (accumulator === undefined || accumulator === null) {
      return undefined;
    }
    const nextValue = accumulator[currentKey];
    return nextValue;
  };

  const splitPath = (p) => p.split('.');

  const processPath = (o, p) => {
    const keys = splitPath(p);
    const finalValue = keys.reduce(reducePath, o);
    return finalValue;
  };

  const isString = (input) => typeof input === 'string';

  const isValidObject = (input) => input !== null && typeof input === 'object';

  if (!isValidObject(obj) || !isString(path)) {
    return undefined;
  }

  return processPath(obj, path);
};

