const generateRange = (start, end, step) => {
  const result = [];
  const pushToArray = (val) => result.push(val);
  const isAscending = start <= end;
  const condition = isAscending ? (i) => i <= end : (i) => i >= end;

  for (let i = start; condition(i); i += step) {
    pushToArray(i);
  }
  return result;
};

const defaultStep = (s) => (s === undefined ? 1 : s);

const range = (start, end, step = 1) => {
  const effectiveStep = defaultStep(step);
  const adjustStep = (s) => (start > end ? -Math.abs(s) : Math.abs(s));
  const finalStep = adjustStep(effectiveStep);

  return generateRange(start, end, finalStep);
};

const logOutput = (arr) => console.log(arr);

logOutput(range(1, 5));
logOutput(range(1, 10, 2));
logOutput(range(5, 1));
logOutput(range(10, 1, 2));

