const wordFrequency = text => {
  const normalizeWord = word => word.toLowerCase().replace(/[^a-z]/g, '');

  const splitAndFilter = str => str.split(/\s+/).filter(word => word.length > 0);

  const countWords = (counts, word) => {
    counts[word] = (counts[word] || 0) + 1;
    return counts;
  };

  const processWords = words => {
    const normalizedWords = words.map(normalizeWord).filter(w => w.length > 0);
    return normalizedWords.reduce(countWords, {});
  };

  const calculateFrequencies = input => processWords(splitAndFilter(input));

  return calculateFrequencies(text);
};

