const isPalindrome = (str) =>
  str === str.split('').reverse().join('');

const longestPalindromeSubstring = (s) => {
  let maxLength = 0;
  let longestPalindrome = '';

  const sLength = s.length;

  const getSubstring = (i, j) => s.substring(i, j + 1);

  for (let i = 0; i < sLength; i++) {
    for (let j = i; j < sLength; j++) {
      const currentSubstring = getSubstring(i, j);
      const currentLength = currentSubstring.length;

      const checkAndUpdate = (sub) => {
        if (isPalindrome(sub) && sub.length > maxLength) {
          maxLength = sub.length;
          longestPalindrome = sub;
        }
      };

      checkAndUpdate(currentSubstring);
    }
  }

  const defaultResult = (s) => s[0] || '';
  return longestPalindrome || defaultResult(s);
};

