const Stack = function() {
  const elements = [];

  this.push = (element) => {
    elements.push(element);
  };

  this.pop = () => elements.length === 0 ? null : elements.pop();

  this.peek = () => elements.length === 0 ? null : elements[elements.length - 1];

  this.isEmpty = () => elements.length === 0;

  this.size = () => elements.length;
};

const createStack = () => new Stack();

