  for (let i = 2, s = Math.sqrt(num); i <= s; i++)
    if (num % i === 0) return false;
  return num > 1;
};

const range = n => Array.from({ length: n }, (_, i) => i + 1);

const filterPrimes = numbers => numbers.filter(isPrime);

const sumArray = arr => arr.reduce((acc, val) => acc + val, 0);

const getPrimesUpTo = n => filterPrimes(range(n));

const sumPrimesUpTo = n => sumArray(getPrimesUpTo(n));

const getPrimesAndSum = n => {
  const primes = getPrimesUpTo(n);
  const totalSum = sumArray(primes);
  return totalSum;
};

const finalSumPrimes = n => {
  const allPrimes = range(n).filter(isPrime);
  return allPrimes.reduce((sum, p) => sum + p, 0);
};

