};

const findSingleNumberXOR = (nums) => {
  const reducer = (accumulator, currentValue) => accumulator ^ currentValue;
  const result = nums.reduce(reducer, 0);

  return result;
};

const findSingleNumberSet = (nums) => {
  const uniqueNums = new Set();
  const sumOfAll = nums.reduce((sum, num) => sum + num, 0);
  nums.forEach(num => uniqueNums.add(num));

  const sumOfUnique = [...uniqueNums].reduce((sum, num) => sum + num, 0);

  return 2 * sumOfUnique - sumOfAll;
};

