const generateRandomChar = () => {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  return chars.charAt(Math.floor(Math.random() * chars.length));
};

const generateShortCode = (length) => Array.from({ length }, generateRandomChar).join('');

const hashUrl = (url) => {
  let hash = 0;
  for (let i = 0; i < url.length; i++) {
    const char = url.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash |= 0; // Convert to 32bit integer
  }
  return Math.abs(hash);
};

const convertToBase62 = (num) => {
  const chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
  let result = '';
  while (num > 0) {
    result = chars[num % 62] + result;
    num = Math.floor(num / 62);
  }
  return result || '0';
};

const padShortCode = (code, length) => code.padStart(length, '0').slice(-length);

const shortenUrl = (longUrl) => {
  const hashedValue = hashUrl(longUrl);
  const base62Code = convertToBase62(hashedValue);
  const shortCode = padShortCode(base62Code, 6);
  return shortCode.length === 6 ? shortCode : generateShortCode(6);
};

