const transposeMatrix = matrix => {
  if (!matrix || matrix.length === 0) return [];

  const numRows = matrix.length;
  const numCols = matrix[0].length;

  const createRow = length => Array.from({ length }, () => 0);
  const createTransposedMatrix = (rows, cols) => Array.from({ length: cols }, () => createRow(rows));

  const transposed = createTransposedMatrix(numRows, numCols);

  const fillTransposed = (rowIdx, colIdx) => {
    transposed[colIdx][rowIdx] = matrix[rowIdx][colIdx];
  };

  const iterateCols = rowIdx => {
    for (let colIdx = 0; colIdx < numCols; colIdx++) {
      fillTransposed(rowIdx, colIdx);
    }
  };

  for (let rowIdx = 0; rowIdx < numRows; rowIdx++) {
    iterateCols(rowIdx);
  }

  return transposed;
};

