    transposed[colIdx][rowIdx] = matrix[rowIdx][colIdx];
  };

  const iterateCols = function(rowIdx) {
    for (let colIdx = 0; colIdx < numCols; colIdx++) {
      fillTransposed(rowIdx, colIdx);
    }
  };

  for (let rowIdx = 0; rowIdx < numRows; rowIdx++) {
    iterateCols(rowIdx);
  }

  return transposed;
};

