const countInversions = nums => {
  let inversions = 0;

  const merge = (left, right) => {
    let merged = [];
    let i = 0, j = 0;
    while (i < left.length && j < right.length) {
      if (left[i] <= right[j]) {
        merged.push(left[i++]);
      } else {
        merged.push(right[j++]);
        inversions += (left.length - i);
      }
    }
    return merged.concat(left.slice(i)).concat(right.slice(j));
  };

  const mergeSort = arr => {
    if (arr.length <= 1) return arr;
    const mid = Math.floor(arr.length / 2);
    const leftHalf = arr.slice(0, mid);
    const rightHalf = arr.slice(mid);
    return merge(mergeSort(leftHalf), mergeSort(rightHalf));
  };

  mergeSort(nums);
  return inversions;
};

const example1 = [2, 4, 1, 3, 5];
const example2 = [1, 2, 3];
const example3 = [5, 4, 3, 2, 1];

const result1 = countInversions(example1);
const result2 = countInversions(example2);
const result3 = countInversions(example3);

const logResult = (arr, count) => console.log(`Array: [${arr.join(', ')}], Inversions: ${count}`);

logResult(example1, result1);
logResult(example2, result2);
logResult(example3, result3);

