const isPlainOperation = op => op !== null && typeof op === 'object' && !Array.isArray(op);

const normalizeType = raw => (typeof raw === 'string' ? raw.trim().toLowerCase() : '');

const validateOperation = (op, index) => {
  if (!isPlainOperation(op)) {
    throw new TypeError(`Operation at index ${index} must be an object`);
  }
  const type = normalizeType(op.type);
  if (type !== 'enqueue' && type !== 'dequeue') {
    throw new TypeError(`Operation at index ${index} has unknown type "${op.type}"`);
  }
  if (type === 'enqueue' && !('value' in op)) {
    throw new TypeError(`Enqueue at index ${index} is missing a value`);
  }
  return type;
};

const applyOperation = (queue, op, index) => {
  const type = validateOperation(op, index);
  if (type === 'enqueue') {
    queue.push(op.value);
    return { type, value: op.value, removed: undefined };
  }
  const removed = queue.shift();
  return { type, value: undefined, removed };
};

const simulateQueue = (initialQueue, operations) => {
  if (!Array.isArray(initialQueue)) {
    throw new TypeError('initialQueue must be an array');
  }
  if (!Array.isArray(operations)) {
    throw new TypeError('operations must be an array');
  }
  const queue = initialQueue.slice();
  operations.forEach((op, index) => applyOperation(queue, op, index));
  return queue;
};

const traceQueue = (initialQueue, operations) => {
  const queue = initialQueue.slice();
  return operations.map((op, index) => {
    const result = applyOperation(queue, op, index);
    return { ...result, snapshot: queue.slice() };
  });
};

const formatValue = value => (value === undefined ? '-' : JSON.stringify(value));

const describeStep = (step, index) => {
  const label = step.type === 'enqueue'
    ? `enqueue ${formatValue(step.value)}`
    : `dequeue ${formatValue(step.removed)}`;
  return `${index + 1}. ${label.padEnd(16)} => [${step.snapshot.map(formatValue).join(', ')}]`;
};

const report = (initialQueue, operations) => {
  const lines = traceQueue(initialQueue, operations).map(describeStep);
  const header = `start: [${initialQueue.map(formatValue).join(', ')}]`;
  return [header, ...lines].join('\n');
};

const main = () => {
  const cases = [
    { queue: [1, 2], ops: [{ type: 'enqueue', value: 3 }, { type: 'dequeue' }] },
    { queue: [], ops: [{ type: 'enqueue', value: 'A' }] },
  ];
  cases.forEach(({ queue, ops }) => {
    console.log(report(queue, ops));
    console.log(`final: [${simulateQueue(queue, ops).map(formatValue).join(', ')}]\n`);
  });
};

main();

module.exports = { simulateQueue, traceQueue, report };

