const normalizeString = str => str.toLowerCase().replace(/[^a-z]/g, '');

const charCountMap = str => {
  const charMap = {};
  for (const char of str) {
    charMap[char] = (charMap[char] || 0) + 1;
  }
  return charMap;
};

const mapsAreEqual = (map1, map2) => {
  const keys1 = Object.keys(map1);
  const keys2 = Object.keys(map2);

  if (keys1.length !== keys2.length) return false;

  return keys1.every(key => map1[key] === map2[key]);
};

const areAnagrams = (str1, str2) => {
  const normalizedStr1 = normalizeString(str1);
  const normalizedStr2 = normalizeString(str2);

  if (normalizedStr1.length !== normalizedStr2.length) return false;

  const map1 = charCountMap(normalizedStr1);
  const map2 = charCountMap(normalizedStr2);

  return mapsAreEqual(map1, map2);
};

