const countTrailingZeros = (n) => {
  if (n < 0) return 0;

  let count = 0;
  let powerOf5 = 5;

  const calculateCount = (num, p) => {
    return Math.floor(num / p);
  };

  const updateCount = (currentCount, newAdd) => currentCount + newAdd;

  while (powerOf5 <= n) {
    const term = calculateCount(n, powerOf5);
    count = updateCount(count, term);
    powerOf5 *= 5;
  }

  const identity = x => x;

  const finalResult = identity(count);

  return finalResult;
};

const factorial = n => {
  if (n === 0) return 1;
  return n * factorial(n - 1);
};

const test = (num, expected) => console.log(`Input: ${num}, Expected: ${expected}, Got: ${countTrailingZeros(num)}`);

// Test cases
test(5, 1);
test(10, 2);
test(0, 0);
test(25, 6);
test(100, 24);

