const MOVES = ['rock', 'paper', 'scissors'];

const BEATS = {
  rock: 'scissors',
  paper: 'rock',
  scissors: 'paper'
};

const normalize = choice => String(choice).trim().toLowerCase();

const isValidMove = choice => MOVES.includes(normalize(choice));

const playRPSRound = (player1Choice, player2Choice) => {
  const p1 = normalize(player1Choice);
  const p2 = normalize(player2Choice);

  if (!isValidMove(p1) || !isValidMove(p2)) {
    throw new Error(`Invalid move: choices must be one of ${MOVES.join(', ')}`);
  }

  if (p1 === p2) {
    return "It's a Tie!";
  }

  return BEATS[p1] === p2 ? 'Player 1 Wins' : 'Player 2 Wins';
};

const scoreRound = ([a, b]) => ({
  player1: normalize(a),
  player2: normalize(b),
  result: playRPSRound(a, b)
});

const playMatch = (rounds) => rounds.map(scoreRound);

const addRound = (totals, round) => {
  if (round.result === 'Player 1 Wins') totals.player1 += 1;
  else if (round.result === 'Player 2 Wins') totals.player2 += 1;
  else totals.ties += 1;
  return totals;
};

const tallyMatch = (results) =>
  results.reduce(addRound, { player1: 0, player2: 0, ties: 0 });

const formatRound = (round, index) =>
  `Round ${index + 1}: ${round.player1} vs ${round.player2} -> ${round.result}`;

const describeTally = ({ player1, player2, ties }) => {
  const leader = player1 === player2
    ? 'Match drawn'
    : `Match winner: Player ${player1 > player2 ? 1 : 2}`;
  return `Score — P1: ${player1}, P2: ${player2}, Ties: ${ties}. ${leader}`;
};

const report = (rounds) => {
  const results = playMatch(rounds);
  const lines = results.map(formatRound);
  lines.push(describeTally(tallyMatch(results)));
  return lines.join('\n');
};

const main = () => {
  const rounds = [
    ['rock', 'scissors'],
    ['paper', 'paper'],
    ['Scissors', ' rock '],
    ['paper', 'scissors'],
    ['rock', 'paper']
  ];

  console.log(report(rounds));

  try {
    playRPSRound('rock', 'lizard');
  } catch (err) {
    console.log(`Rejected: ${err.message}`);
  }
};

main();

module.exports = { playRPSRound, playMatch, tallyMatch, report };

