const containsSubarray = (mainArray, subArray) => {
  const mainLength = mainArray.length;
  const subLength = subArray.length;

  if (subLength === 0) return true;
  if (subLength > mainLength) return false;

  const getSlice = (arr, start, end) => arr.slice(start, end);

  const checkSlice = (i) => {
    const currentSlice = getSlice(mainArray, i, i + subLength);
    return arraysAreEqual(currentSlice, subArray);
  };

  const range = Array.from({ length: mainLength - subLength + 1 }, (_, i) => i);

  const anyMatch = range.some(checkSlice);

  return anyMatch;
};

