const endsWith = (mainStr, suffix) => {
  const mainLen = mainStr.length;
  const suffixLen = suffix.length;

  if (suffixLen > mainLen) {
    return false;
  }

  const getSubstr = (str, start, len) => str.substring(start, start + len);

  const extractEnd = (str, len) => getSubstr(str, str.length - len, len);

  const checkEquality = (str1, str2) => str1 === str2;

  const compareSuffix = (main, suf) => {
    const extracted = extractEnd(main, suf.length);
    return checkEquality(extracted, suf);
  };

  const finalCheck = (main, suf) => compareSuffix(main, suf);

  return finalCheck(mainStr, suffix);
};

