  if (suffixLen > mainLen) {
    return false;
  }

  const getSubstr = function(str, start, len) { return str.substring(start, start + len); };

  const extractEnd = function(str, len) { return getSubstr(str, str.length - len, len); };

  const checkEquality = function(str1, str2) { return str1 === str2; };

  const compareSuffix = function(main, suf) {
    const extracted = extractEnd(main, suf.length);
    return checkEquality(extracted, suf);
  };

  const finalCheck = function(main, suf) { return compareSuffix(main, suf); };

  return finalCheck(mainStr, suffix);
};

