const calculateCompoundInterest = (principal, rate, n, years) => {
  const calculateExponent = (compoundingFreq, numYears) => compoundingFreq * numYears;
  const calculateRatePerPeriod = (annualRate, compoundingFreq) => annualRate / compoundingFreq;
  const addOne = val => 1 + val;
  const power = (base, exp) => Math.pow(base, exp);
  const multiplyPrincipal = (baseValue, initialPrincipal) => baseValue * initialPrincipal;

  const exponent = calculateExponent(n, years);
  const ratePerPeriod = calculateRatePerPeriod(rate, n);
  const base = addOne(ratePerPeriod);
  const powerResult = power(base, exponent);
  return multiplyPrincipal(powerResult, principal);
};

