const isValidEmail = email => {
  const containsAt = str => str.includes('@');
  const containsDot = str => str.includes('.');
  const startsWithSpecial = str => str.startsWith('@') || str.startsWith('.');
  const endsWithSpecial = str => str.endsWith('@') || str.endsWith('.');

  const hasNoDoubleAt = str => str.indexOf('@') === str.lastIndexOf('@');
  const hasAtAndDot = str => containsAt(str) && containsDot(str);

  const isNotEdgeCase = str => !startsWithSpecial(str) && !endsWithSpecial(str);

  return hasAtAndDot(email) && isNotEdgeCase(email) && hasNoDoubleAt(email);
};

