const levenshteinDistance = (s1, s2) => {
  const m = s1.length;
  const n = s2.length;

  const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  const initializeRows = (arr, length) => Array.from({ length }, (_, i) => i);
  const initializeCols = (arr, length) => Array.from({ length }, (_, i) => { arr[i][0] = i; return arr; });

  dp[0] = initializeRows(dp[0], n + 1);
  initializeCols(dp, m + 1);

  const calculateMin = (a, b, c) => Math.min(a, b, c);

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = s1[i - 1] === s2[j - 1] ? 0 : 1;
      const substitutionCost = dp[i - 1][j - 1] + cost;
      const insertionCost = dp[i][j - 1] + 1;
      const deletionCost = dp[i - 1][j] + 1;

      dp[i][j] = calculateMin(substitutionCost, insertionCost, deletionCost);
    }
  }

  return dp[m][n];
};

