  const ranks = ['2', '3', '4', '5', '6', '7', '8', '9', 'T', 'J', 'Q', 'K', 'A'];

  const combineCard = function(rank, suit) { return rank + suit; };
  const flatMap = function(arr, fn) { return arr.reduce(function(acc, x) { return acc.concat(fn(x)); }, []); };

  return flatMap(suits, function(suit) { return ranks.map(function(rank) { return combineCard(rank, suit); }); });
};

