const debounce = (func, delay) => {
  let timeoutId;

  const debounced = (...args) => {
    const later = () => {
      clearTimeout(timeoutId);
      func(...args);
    };

    clearTimeout(timeoutId);
    timeoutId = setTimeout(later, delay);
  };

  return debounced;
};

const logHello = () => console.log('Hello');
const debouncedLog = debounce(logHello, 200);

debouncedLog();
debouncedLog();

const saveData = data => console.log('Saving data:', data);
const debouncedSave = debounce(saveData, 500);

debouncedSave('Initial');
setTimeout(() => debouncedSave('Second'), 100);
setTimeout(() => debouncedSave('Third'), 400);

