  const [protocolPart, rest] = splitAtFirst(url, '://');
  const protocol = protocolPart;

  const getHostAndPath = remaining => {
    const firstSlashIndex = remaining.indexOf('/');
    return firstSlashIndex === -1
      ? { host: remaining, path: '' }
