const isValidParentheses = s => {
  const stack = [];
  const bracketMap = { '(': ')', '{': '}', '[': ']' };
  const isOpenBracket = char => bracketMap.hasOwnProperty(char);
  const isMatchingPair = (open, close) => bracketMap[open] === close;

  for (const char of s) {
    if (isOpenBracket(char)) {
      stack.push(char);
    } else {
      if (stack.length === 0) return false;
      const lastOpen = stack.pop();
      if (!isMatchingPair(lastOpen, char)) return false;
    }
  }

  return stack.length === 0;
};

const test1 = '()[]{}';
const test2 = '([)]';
const test3 = '{[]}';
const test4 = '({[]})';
const test5 = '';
const test6 = '[';

const results = [
  isValidParentheses(test1),
  isValidParentheses(test2),
  isValidParentheses(test3),
  isValidParentheses(test4),
  isValidParentheses(test5),
  isValidParentheses(test6)
];

console.log(results.map(r => r ? "Valid" : "Invalid").join(', '));

