const clockAngle = (hours, minutes) => {
  const getHourDegrees = (h, m) => ((h % 12) + m / 60) * 30;
  const getMinuteDegrees = m => m * 6;
  const calculateDifference = (deg1, deg2) => Math.abs(deg1 - deg2);
  const normalizeAngle = angle => Math.min(angle, 360 - angle);

  const hourDegrees = getHourDegrees(hours, minutes);
  const minuteDegrees = getMinuteDegrees(minutes);
  const rawAngle = calculateDifference(hourDegrees, minuteDegrees);

  return normalizeAngle(rawAngle);
};

