const groupAnagrams = (strs) => {
  const anagramMap = new Map();

  const sortString = (str) => [...str].sort().join('');

  strs.forEach(str => {
    const sortedStr = sortString(str);
    const existingGroup = anagramMap.get(sortedStr) || [];
    anagramMap.set(sortedStr, [...existingGroup, str]);
  });

  const getValues = (map) => Array.from(map.values());

  const result = getValues(anagramMap);
  return result;
};

const example1 = ['eat', 'tea', 'tan', 'ate', 'nat', 'bat'];
const example2 = ['a', 'b', 'c'];
const example3 = ['listen', 'silent', 'enlist'];

