const atm = initialBalance => {
  let balance = initialBalance;

  const formatCurrency = amount => `$${amount.toFixed(2)}`;

  const deposit = amount => {
    balance += amount;
    return `Deposited ${formatCurrency(amount)}. New balance: ${formatCurrency(balance)}.`;
  };

  const withdraw = amount => {
    if (balance >= amount) {
      balance -= amount;
      return `Withdrew ${formatCurrency(amount)}. New balance: ${formatCurrency(balance)}.`;
    }
    return `Insufficient funds. Current balance: ${formatCurrency(balance)}.`;
  };

  const checkBalance = () => `Current balance: ${formatCurrency(balance)}.`;

  return { deposit, withdraw, checkBalance };
};

