const findKthSmallest = (arr, k) => {
  const swap = (arr, i, j) => ([arr[i], arr[j]] = [arr[j], arr[i]]);

  const partition = (arr, left, right, pivotIndex) => {
    const pivotValue = arr[pivotIndex];
    swap(arr, pivotIndex, right);
    let storeIndex = left;
    for (let i = left; i < right; i++) {
      if (arr[i] < pivotValue) {
        swap(arr, storeIndex, i);
        storeIndex++;
      }
    }
    swap(arr, right, storeIndex);
    return storeIndex;
  };

  const quickselect = (arr, left, right, kSmallest) => {
    if (left === right) return arr[left];

    const pivotIndex = Math.floor(Math.random() * (right - left + 1)) + left;
    const newPivotIndex = partition(arr, left, right, pivotIndex);
    const pivotRank = newPivotIndex - left + 1;

    if (kSmallest === pivotRank) return arr[newPivotIndex];
    else if (kSmallest < pivotRank) return quickselect(arr, left, newPivotIndex - 1, kSmallest);
    else return quickselect(arr, newPivotIndex + 1, right, kSmallest - pivotRank);
  };

  return quickselect([...arr], 0, arr.length - 1, k);
};

