const convertBase10 = (num, base) => {
  if (num === 0) return '0';

  const chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  let result = [];
  let currentNum = num;

  const getChar = (digit) => chars[digit];

  const pushDigit = (digit) => result.unshift(getChar(digit));

  const divide = (n, b) => Math.floor(n / b);

  const getRemainder = (n, b) => n % b;

  while (currentNum > 0) {
    const remainder = getRemainder(currentNum, base);
    pushDigit(remainder);
    currentNum = divide(currentNum, base);
  }

  const joinResult = (arr) => arr.join('');

  return joinResult(result);
};

