const memoize = (func) => {
  const cache = new Map();

  const getCacheKey = (...args) => JSON.stringify(args);

  const memoized = (...args) => {
    const key = getCacheKey(...args);
    if (cache.has(key)) {
      return cache.get(key);
    }
    const result = func.apply(memoized, args); 
    const setCache = (k, v) => cache.set(k, v);
    setCache(key, result);
    return result;
  };

  return memoized;
};

