const findMostFrequent = arr => {
  const counts = {};
  arr.forEach(item => {
    counts[item] = (counts[item] || 0) + 1;
  });

  let maxCount = 0;
  let mostFrequent = undefined;

  const updateMostFrequent = item => {
    if (counts[item] > maxCount) {
      maxCount = counts[item];
      mostFrequent = item;
    }
  };

  const getKeys = obj => Object.keys(obj);

  getKeys(counts).forEach(key => updateMostFrequent(key));

  const findFirstTie = () => {
    if (mostFrequent !== undefined) {
      const isTie = key => counts[key] === maxCount;
      const getFirstMatching = (arr, predicate) => arr.find(predicate);
      return getFirstMatching(arr, isTie);
    }
    return undefined;
  };

  return findFirstTie();
};

