const isValidDate = dateStr => {
  const dateParts = dateStr.split('-');
  if (dateParts.length !== 3) return false;

  const toInt = part => parseInt(part, 10);
  const [year, month, day] = dateParts.map(toInt);

  const isValidYear = y => y >= 1000 && y <= 9999;
  const isValidMonth = m => m >= 1 && m <= 12;
  const isValidDay = d => d >= 1 && d <= 31;

  if (![year, month, day].every(part => !isNaN(part))) return false;
  if (!isValidYear(year) || !isValidMonth(month) || !isValidDay(day)) return false;

  const isLeapYear = y => (y % 4 === 0 && y % 100 !== 0) || (y % 400 === 0);

  const daysInMonth = (m, y) => {
    switch (m) {
      case 2:
        return isLeapYear(y) ? 29 : 28;
      case 4:
      case 6:
      case 9:
      case 11:
        return 30;
      default:
        return 31;
    }
  };

  return day <= daysInMonth(month, year);
};

