  const isValidMonth = function(m) { return m >= 1 && m <= 12; };
  const isValidDay = function(d) { return d >= 1 && d <= 31; };

  if (![year, month, day].every(function(part) { return !isNaN(part); })) return false;
  if (!isValidYear(year) || !isValidMonth(month) || !isValidDay(day)) return false;

  const isLeapYear = function(y) { return (y % 4 === 0 && y % 100 !== 0) || (y % 400 === 0); };

  const daysInMonth = function(m, y) {
    switch (m) {
      case 2:
        return isLeapYear(y) ? 29 : 28;
      case 4:
      case 6:
      case 9:
      case 11:
        return 30;
      default:
        return 31;
    }
  };

  return day <= daysInMonth(month, year);
};

