const createEditor = () => {
  let states = [''];
  let currentStateIndex = 0;

  const getCurrentText = () => states[currentStateIndex];

  const typeText = text => {
    states = states.slice(0, currentStateIndex + 1);
    states.push(text);
    currentStateIndex++;
  };

  const undo = () => {
    if (currentStateIndex > 0) {
      currentStateIndex--;
    }
    return states[currentStateIndex];
  };

  const redo = () => {
    if (currentStateIndex < states.length - 1) {
      currentStateIndex++;
    }
    return states[currentStateIndex];
  };

  return { typeText, undo, redo, getCurrentText };
};

