const trailingZerosInFactorial = n => {
  const isNonNegative = x => x >= 0;
  if (!isNonNegative(n)) return 0;

  const calculateFives = num => {
    let count = 0;
    for (let i = 5; Math.floor(num / i) >= 1; i *= 5) {
      count += Math.floor(num / i);
    }
    return count;
  };

  const calculateTwos = num => {
    let count = 0;
    for (let i = 2; Math.floor(num / i) >= 1; i *= 2) {
      count += Math.floor(num / i);
    }
    return count;
  };

  const minOfTwo = (a, b) => Math.min(a, b);

  const fiveCount = calculateFives(n);
  const twoCount = calculateTwos(n);

  return minOfTwo(fiveCount, twoCount);
};

