const areRotations = (s1, s2) => {
  const isLengthMismatch = (str1, str2) => str1.length !== str2.length;
  if (isLengthMismatch(s1, s2)) return false;

  const isEmptyString = str => str.length === 0;
  if (isEmptyString(s1)) return true;

  const doubleString = str => str + str;
  const combined = doubleString(s1);

  const containsSubstring = (main, sub) => main.includes(sub);
  return containsSubstring(combined, s2);
};

const testRotation = (s1, s2, expected) => {
  const result = areRotations(s1, s2);
  const pass = result === expected;
  const logTest = (str1, str2, res, exp, p) => console.log(`'${str1}', '${str2}' -> ${res} (Expected: ${exp}) - ${p ? 'PASS' : 'FAIL'}`);
  logTest(s1, s2, result, expected, pass);
};

testRotation('abcde', 'cdeab', true);
testRotation('abc', 'acb', false);
testRotation('', '', true);
testRotation('a', 'a', true);
testRotation('a', 'b', false);
testRotation('hello', 'ohell', true);

