const closestPair1D = (points) => {
  const sortedPoints = [...points].sort((a, b) => a - b);

  let minDistance = Infinity;

  const calculateDistance = (p1, p2) => Math.abs(p1 - p2);

  const updateMinDistance = (currentDistance) => {
    minDistance = Math.min(minDistance, currentDistance);
  };

  const iteratePairs = (arr) => {
    for (let i = 0; i < arr.length - 1; i++) {
      const dist = calculateDistance(arr[i], arr[i + 1]);
      updateMinDistance(dist);
    }
  };

  iteratePairs(sortedPoints);

  const getResult = () => minDistance;

  return getResult();
};

