const filterByDateRange = (items, startDate, endDate) => {
  const parseDate = dateString => new Date(dateString);
  const start = parseDate(startDate);
  const end = parseDate(endDate);

  const isWithinRange = item => {
    const itemDate = parseDate(item.date);
    const isAfterStart = itemDate >= start;
    const isBeforeEnd = itemDate <= end;
    return isAfterStart && isBeforeEnd;
  };

  const filterItems = (arr, predicate) => arr.filter(predicate);

  return filterItems(items, isWithinRange);
};

