const findMissingNumber = nums => {
  const n = nums.length;
  const expectedSum = n * (n + 1) / 2;

  const actualSum = nums.reduce((acc, num) => acc + num, 0);

  const calculateDifference = (expected, actual) => expected - actual;

  const isGreaterThanZero = val => val > 0;

  const getMissing = (diff) => {
    if (isGreaterThanZero(diff)) return diff;
    return 0;
  };

  const difference = calculateDifference(expectedSum, actualSum);

  return getMissing(difference);
};

