const columnToNumber = (columnTitle) => {
  const charToInt = (char) => char.charCodeAt(0) - 'A'.charCodeAt(0) + 1;

  const toArray = (str) => Array.from(str);

  const calculateNumber = (acc, char) => acc * 26 + charToInt(char);

  const reverseAndReduce = (arr) => arr.reduce(calculateNumber, 0);

  const result = toArray(columnTitle).reduce((acc, char, index, arr) => {
    const power = arr.length - 1 - index;
    const charValue = charToInt(char);
    return acc + charValue * Math.pow(26, power);
  }, 0);

  return result;
};

