const rotateMatrix = (matrix) => {
  const n = matrix.length;

  const transpose = (m) => {
    for (let i = 0; i < n; i++) {
      for (let j = i; j < n; j++) {
        [m[i][j], m[j][i]] = [m[j][i], m[i][j]];
      }
    }
  };

  const reverseRows = (m) => {
    m.forEach(row => {
      row.reverse();
    });
  };

  const swap = (arr, i, j) => {
    [arr[i], arr[j]] = [arr[j], arr[i]];
  };

  const flipHorizontally = (m) => {
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < Math.floor(n / 2); j++) {
        swap(m[i], j, n - 1 - j);
      }
    }
  };

  const rotate = (m) => {
    transpose(m);
    flipHorizontally(m);
  };

  rotate(matrix);
};

